const $=s=>document.querySelector(s),assert=(x,m)=>{if(!x)throw Error(m);},sleep=ms=>new Promise(r=>setTimeout(r,ms));
const storedKey='openplay-midi-keyshift-check-v1';
const sourceFiles=['app.js','panels.js','midi.js','engine.js','keylock.js','keylock-shadow-live.js','midi-keyshift-harness.js','index.html'];
const sha=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
const bounded=(promise,label,ms=5000)=>{let timer;return Promise.race([promise,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error(label+' timed out')),ms))]).finally(()=>clearTimeout(timer));};
const sourceHashes=async()=>bounded(Promise.all(sourceFiles.map(async p=>{const response=await fetch(p);assert(response.ok,'Source fetch failed '+p);return[p,await sha(await response.arrayBuffer())];})).then(Object.fromEntries),'Source identity');
async function until(predicate,label,ms=15000){const end=performance.now()+ms;while(!predicate()){assert(performance.now()<end,label+' timed out');await sleep(15);}}
function field(selector,value){const e=$(selector);assert(e,'Missing '+selector);e.value=String(value);e.dispatchEvent(new Event(e.tagName==='SELECT'?'change':'input',{bubbles:true}));}
function click(selector){const e=$(selector);assert(e,'Missing '+selector);e.click();}
const b64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);};
function toneFrequency(data,sr){let mean=0;for(const v of data){assert(Number.isFinite(v),'Non-finite decoded PCM');mean+=v;}mean/=data.length;let power=0,peak=0;const crossings=[];for(let i=0;i<data.length;i++){const v=data[i]-mean;power+=v*v;peak=Math.max(peak,Math.abs(v));if(i&&data[i-1]-mean<0&&v>=0)crossings.push(i-1-(data[i-1]-mean)/(data[i]-data[i-1]));}return{frames:data.length,rms:Math.sqrt(power/data.length),peak,hz:crossings.length>1?(crossings.length-1)*sr/(crossings.at(-1)-crossings[0]):null};}
let previous=null,downloadURL=null;try{previous=JSON.parse(localStorage.getItem(storedKey)||'null');}catch{}
let app;
async function loadActualApp(){const markup=await(await fetch('index.html')).text(),parsed=new DOMParser().parseFromString(markup,'text/html');for(const e of [...parsed.body.children])if(e.tagName!=='SCRIPT')document.body.append(e);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track&&window.openPlay?.state.decks[1].track,'Actual default decks');app=window.openPlay;$('#midi-check-run').textContent=previous?'Run restored mapping and audio check':'Run mapper and rendered-audio checks';$('#midi-check-run').disabled=false;$('#midi-check-status').textContent=previous?'Phase1 evidence retained; reload happened. Run restoration phase.':'Ready; isolated test storage.';}
function publish(report){$('#midi-check-results').textContent=JSON.stringify({...report,recordings:report.recordings.map(({base64,...r})=>({...r,base64:'Complete encoded recording retained in download'}))},null,2);$('#midi-check-status').textContent=`${report.phase}: ${report.checks.filter(c=>c.passed).length}/${report.checks.length} checks; ${report.fatalErrors.length} fatal; ${report.completed?'scoped phase passed':'acceptance incomplete'}`;if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=$('#midi-check-download');a.hidden=false;a.href=downloadURL;a.download=`midi-keyshift-browser-${report.phase}-results.json`;}
async function run(){const {state,engine}=app,phase=previous?'restored':'initial',report={phase,startedAt:new Date().toISOString(),checks:[],fatalErrors:[],recordings:[],sourceBefore:{},fixture:{origin:location.origin,framesPerSource:48000*60,sampleRate:48000,deck1Hz:[330,550],deck2Hz:[440,660],amplitude:.12},criteria:{frequencyAbsoluteHz:1,frequencyRelative:.005,minimumRMS:.01,measurementStartSeconds:.2,measurementEndSeconds:1.1,minimumRecordingSeconds:1.2},scope:'Controlled original tone buffers in actual app; DOM mapper/learn/Add/injection callbacks, actual engine/WASM and complete postmaster recordings. Programmatic DOM interactions, no physical/native/vendor/continuity acceptance.',physicalOutputMuted:false,completed:false};
 async function check(name,fn){const evidence={};try{await fn(evidence);report.checks.push({name,passed:true,evidence});}catch(error){report.checks.push({name,passed:false,evidence,error:error.message,stack:error.stack});}publish(report);}
 const deckButton=(i,action)=>`[data-deck="${i}"][data-action="${action}"]`;
 function openMIDI(){if(!$('#modal').open)click('[data-panel="midi"]');assert($('#midi-target'),'Mapper is not open');}
 function message({number,value,encoding='7-bit absolute',target='Deck 1 key shift'}){openMIDI();field('#midi-target',target);field('#midi-encoding',encoding);field('#midi-channel',1);field('#midi-number',number);field('#midi-type','CC');field('#midi-test-value',value);click('#midi-send');}
 async function addMapping({target,number,encoding='7-bit absolute',learn=false}){openMIDI();field('#midi-target',target);field('#midi-encoding',encoding);field('#midi-channel',1);field('#midi-number',number);field('#midi-type','CC');if(learn){const before=state.decks.map(d=>d.keyShift||0);click('#midi-learn');field('#midi-test-value',96);click('#midi-send');await until(()=>$('#midi-learn').textContent==='Learn next message','Learn receipt');assert(JSON.stringify(state.decks.map(d=>d.keyShift||0))===JSON.stringify(before),'Learn dispatched an ordinary action');}const count=state.mappings.length;click('#midi-add');assert(state.mappings.length===count+1,'Add did not persist mapping');return structuredClone(state.mappings.at(-1));}
 async function play(i){if($('#modal').open)click('#modal-close');click(deckButton(i,'play'));await until(()=>state.decks[i].playing&&!state.decks[i].processing,'Deck playing');}
 async function pause(i){if($('#modal').open)click('#modal-close');if(state.decks[i].playing||state.decks[i].processing)click(deckButton(i,'play'));await until(()=>!state.decks[i].playing&&!state.decks[i].processing,'Deck paused');}
 async function record(label,expected){await sleep(500);await engine.recordStart();await sleep(1500);const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());const item={label,format:blob.type,bytes:bytes.length,sha256:await sha(bytes),base64:b64(bytes),expectedHz:expected,measured:[]};report.recordings.push(item);let audio;try{audio=await bounded(engine.ctx.decodeAudioData(bytes.buffer.slice(0)),'Recording decode');}catch(error){item.decodeError=error.message;throw error;}item.decoded={frames:audio.length,sampleRate:audio.sampleRate,channels:audio.numberOfChannels,duration:audio.duration};assert(audio.duration>=report.criteria.minimumRecordingSeconds&&audio.numberOfChannels===2,'Incomplete stereo recording');for(let c=0;c<2;c++){const all=audio.getChannelData(c);for(const x of all)assert(Number.isFinite(x),'Non-finite whole recording');const start=Math.round(.2*audio.sampleRate),end=Math.round(Math.min(1.1,audio.duration-.1)*audio.sampleRate);const m=toneFrequency(all.subarray(start,end),audio.sampleRate);item.measured.push(m);assert(m.rms>.01&&m.hz!==null&&Math.abs(m.hz-expected[c])<=Math.max(1,expected[c]*.005),'Recorded pitch mismatch '+JSON.stringify({c,expected:expected[c],measured:m}));}return{label,sha256:item.sha256,decoded:item.decoded,expectedHz:expected,measured:item.measured};}
 try{
  report.sourceBefore=await sourceHashes();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute applied',2000);report.physicalOutputMuted=engine.audioMonitor.snapshot().physicalMuted;assert(report.physicalOutputMuted,'Physical route not muted');
  for(let i=0;i<2;i++){const d=state.decks[i],buffer=engine.ctx.createBuffer(2,48000*60,48000);for(let c=0;c<2;c++){const a=buffer.getChannelData(c),hz=report.fixture[i===0?'deck1Hz':'deck2Hz'][c];for(let n=0;n<a.length;n++)a[n]=.12*Math.sin(2*Math.PI*hz*n/48000);}engine.buffers.set(d.track.id,buffer);engine.clearDeckScratchCache(i);}
  await check('Actual target selector contains both deck Key Shift actions',async e=>{openMIDI();e.targets=[...$('#midi-target').options].map(x=>x.value);assert([1,2,3,4].every(n=>e.targets.includes('Deck '+n+' key shift')),'Key Shift target is missing');});
  if(!previous){
   await check('Learn captures without changing pitch; Add preserves prior browse mapping',async e=>{assert(state.mappings.length===0,'Use a fresh isolated origin for initial phase');e.browse=await addMapping({target:'Library browse',number:1,encoding:'Relative two’s complement'});e.shift=await addMapping({target:'Deck 1 key shift',number:16,learn:true});assert(state.mappings[0].target==='Library browse','Browse mapping overwritten');e.saved=JSON.parse(localStorage.getItem('openplay-review-v1')).mappings;assert(e.saved.length===2,'Mappings were not saved');});
   await check('Tempo at+8% remains pitch-locked before mapped shift',async e=>{click('#modal-close');click(deckButton(0,'keylock'));await until(()=>state.decks[0].keylock,'Key lock');field('[data-tempo="0"]',8);await play(0);e.recording=await record('deck1-neutral-tempo108',[330,550]);assert(state.decks[0].rate===1.08&&state.decks[1].rate===1,'Unexpected deck rates');});
   await check('Mapped absolute+12 changes real stereo PCM and only the addressed deck',async e=>{message({number:16,value:96});await until(()=>state.decks[0].keyShift===12&&!state.decks[0].processing,'Mapped+12');e.recording=await record('deck1-plus12',[660,1100]);assert(state.decks[0].rate===1.08&&(state.decks[1].keyShift||0)===0,'Shift changed tempo or other deck');});
   await check('Mapped negative pitch crosses neutral and keeps the same tempo',async e=>{message({number:16,value:32});await until(()=>state.decks[0].keyShift===-12&&!state.decks[0].processing,'Mapped-12');e.recording=await record('deck1-minus12',[165,275]);assert(state.decks[0].rate===1.08,'Shift changed tempo');await pause(0);});
   await check('Relative deck2 steps change real audio while deck1 pitch stays unchanged',async e=>{e.mapping=await addMapping({target:'Deck 2 key shift',number:17,encoding:'Relative two’s complement',learn:true});message({target:'Deck 2 key shift',number:17,value:1,encoding:'Relative two’s complement'});await until(()=>state.decks[1].keyShift===1,'Relative+1');click('#modal-close');field('[data-tempo="1"]',-8);await play(1);const ratio=2**(1/12);e.recording=await record('deck2-relative-plus1-tempo92',[440*ratio,660*ratio]);assert(state.decks[0].keyShift===-12&&state.decks[0].rate===1.08&&state.decks[1].rate===.92,'Cross-deck or tempo mutation');message({target:'Deck 2 key shift',number:17,value:127,encoding:'Relative two’s complement'});await until(()=>state.decks[1].keyShift===0,'Relative-1');e.resetRecording=await record('deck2-relative-neutral-tempo92',[440,660]);await pause(1);});
   await check('Four-deck mode maps deck3 anddeck4 through actual stereo audio',async e=>{if($('#modal').open)click('#modal-close');field('#deck-count',4);click('[data-track="demo-0"]');click(deckButton(2,'load'));await until(()=>state.decks[2].track?.id==='demo-0','Deck3 load');click('[data-track="demo-1"]');click(deckButton(3,'load'));await until(()=>state.decks[3].track?.id==='demo-1','Deck4 load');e.map3=await addMapping({target:'Deck 3 key shift',number:18});e.map4=await addMapping({target:'Deck 4 key shift',number:19});message({target:'Deck 3 key shift',number:18,value:96});await until(()=>state.decks[2].keyShift===12,'Deck3 mapped+12');await play(2);e.deck3=await record('deck3-plus12',[660,1100]);await pause(2);message({target:'Deck 4 key shift',number:19,value:32});await until(()=>state.decks[3].keyShift===-12,'Deck4 mapped-12');await play(3);e.deck4=await record('deck4-minus12',[220,330]);await pause(3);assert(state.decks[0].keyShift===-12&&state.decks[1].keyShift===0,'Four-deck mapping changed other decks');});
   await check('Legacy relative browse still changes selection without changing saved mappings',async e=>{const before=JSON.stringify(state.mappings),selected=state.selected;message({target:'Library browse',number:1,value:1,encoding:'Relative two’s complement'});await until(()=>state.selected!==selected,'Legacy browse moved');assert(JSON.stringify(state.mappings)===before,'Dispatch edited mappings');e.selected=state.selected;e.saved=JSON.parse(localStorage.getItem('openplay-review-v1')).mappings;report.savedMappings=e.saved;});
  }else{
   await check('Actual reload restored all five mappings unchanged',async e=>{assert(previous.completed&&previous.savedMappings?.length===5,'Initial phase was not accepted');assert(JSON.stringify(state.mappings)===JSON.stringify(previous.savedMappings),'Reload changed mappings');e.restored=structuredClone(state.mappings);});
   await check('Restored relative mapping drives real audio without relearning',async e=>{message({target:'Deck 2 key shift',number:17,value:1,encoding:'Relative two’s complement'});await until(()=>state.decks[1].keyShift===1,'Restored mapping dispatched');await play(1);const ratio=2**(1/12);e.recording=await record('restored-deck2-plus1',[440*ratio,660*ratio]);await pause(1);assert((state.decks[0].keyShift||0)===0,'Restored mapping changed other deck');});
  }
 }catch(error){report.fatalErrors.push({message:error.message,stack:error.stack});}
 finally{for(const d of state.decks)engine.pause(d);if(engine.recording)try{await engine.recordStop();}catch(error){report.fatalErrors.push({phase:'record cleanup',message:error.message});}try{if(engine.ctx)await bounded(engine.ctx.close(),'Context close');}catch(error){report.fatalErrors.push({phase:'context cleanup',message:error.message});}try{report.sourceAfter=await sourceHashes();report.sourceStable=Object.keys(report.sourceBefore).length===sourceFiles.length&&JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);}catch(error){report.sourceStable=false;report.fatalErrors.push({phase:'final identities',message:error.message});}report.completed=report.checks.length===(previous?3:8)&&report.checks.every(c=>c.passed)&&!report.fatalErrors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();publish(report);if(!previous&&report.completed)localStorage.setItem(storedKey,JSON.stringify(report));}
}
$('#midi-check-run').onclick=async()=>{const b=$('#midi-check-run');b.disabled=true;try{await run();}catch(error){$('#midi-check-status').textContent='Harness error: '+error.message;}finally{b.disabled=false;}};
loadActualApp().catch(error=>$('#midi-check-status').textContent='Load failed: '+error.message);
